# dhcpd.conf
omapi-port 7911;

default-lease-time 43200;
max-lease-time 86400;



ddns-update-style none;

option domain-name "lab.cs.ucalgary.ca";
option domain-search "lab.cs.ucalgary.ca", "cs.ucalgary.ca";
option domain-name-servers 172.20.2.11;
option ntp-servers 136.159.5.75;

allow booting;
allow bootp;

option fqdn.no-client-update    on;  # set the "O" and "S" flag bits
option fqdn.rcode2            255;
option pxegrub code 150 = text ;




# Bootfile Handoff
next-server 172.20.2.11;
option architecture code 93 = unsigned integer 16 ;
if option architecture = 00:06 {
  filename "grub2/shim.efi";
} elsif option architecture = 00:07 {
  filename "grub2/shim.efi";
} elsif option architecture = 00:09 {
  filename "grub2/shim.efi";
} else {
  filename "pxelinux.0";
}

log-facility local7;

include "/etc/dhcp/dhcpd.hosts";

# lab.cs.ucalgary.ca
subnet 172.20.2.0 netmask 255.255.255.0 {

  option subnet-mask 255.255.255.0;
  option routers 172.20.2.1;

  range dynamic-bootp 172.20.2.240 172.20.2.254;
}
